#!/usr/bin/env python3
"""Build one self-contained, offline travel album HTML from local photographs."""
import argparse
import base64
import html
import io
import json
import re
import sys
from pathlib import Path
from PIL import Image, ImageOps

try:
    import pillow_heif
    pillow_heif.register_heif_opener()
except ImportError:
    pass

EXTENSIONS = {'.jpg', '.jpeg', '.png', '.webp', '.heic', '.heif', '.tif', '.tiff', '.bmp', '.gif'}


def natural_key(path):
    return [(0, int(part)) if part.isdigit() else (1, part.casefold()) for part in re.split(r'(\d+)', path.name)]


def collect(inputs, title, album_name):
    direct = []
    groups = []
    for raw in inputs:
        path = Path(raw).expanduser().resolve()
        if not path.exists():
            raise ValueError(f'找不到：{path}')
        if path.is_file():
            if path.suffix.lower() in EXTENSIONS:
                direct.append(path)
            continue
        root_images = sorted((p for p in path.iterdir() if p.is_file() and p.suffix.lower() in EXTENSIONS), key=natural_key)
        if root_images:
            groups.append((album_name or path.name, root_images))
        for child in sorted((p for p in path.iterdir() if p.is_dir() and not p.name.startswith('.')), key=natural_key):
            photos = sorted((p for p in child.iterdir() if p.is_file() and p.suffix.lower() in EXTENSIONS), key=natural_key)
            if photos:
                groups.append((child.name, photos))
    if direct:
        groups.insert(0, (album_name or title, direct))
    return groups


def encode_photo(path, max_side, quality):
    with Image.open(path) as original:
        image = ImageOps.exif_transpose(original)
        if image.mode in ('RGBA', 'LA') or (image.mode == 'P' and 'transparency' in image.info):
            canvas = Image.new('RGB', image.size, '#ffffff')
            canvas.paste(image.convert('RGBA'), mask=image.convert('RGBA').getchannel('A'))
            image = canvas
        else:
            image = image.convert('RGB')
        image.thumbnail((max_side, max_side), Image.Resampling.LANCZOS)
        width, height = image.size
        output = io.BytesIO()
        image.save(output, format='JPEG', quality=quality, optimize=True, progressive=True)
    return {'src': 'data:image/jpeg;base64,' + base64.b64encode(output.getvalue()).decode('ascii'),
            'w': width, 'h': height, 'name': path.stem}


